// The components that are inputs take their value and report changes as props (`value`, `onChange`), so any host
// can use them as they are. For Shiny, shiny.react's InputAdapter(component, valueProps) makes each a Shiny input
// (input$<inputId>, updateReactInput()); these are the valueProps each one is made with:
//
//   InputAdapter(ChipSelect, inputValueProps.ChipSelect)
import type { AdjEvent, AdjustmentEditorProps } from "./components/AdjustmentEditor";
import type { CdCheckboxProps } from "./components/CdCheckbox";
import type { CdTextAreaProps } from "./components/CdTextArea";
import type { ChartCustomizeProps, CustomizeValue } from "./components/ChartCustomize";
import type { ChipMultiProps, ChipMultiValue } from "./components/ChipMulti";
import type { ChipNumberProps } from "./components/ChipNumber";
import type { ChipSelectProps } from "./components/ChipSelect";
import type { FieldNumberProps } from "./components/FieldNumber";
import type { FieldSelectProps } from "./components/FieldSelect";
import type { MappingModalProps } from "./components/MappingModal";
import type { WizardStepsProps } from "./components/WizardSteps";

/** Maps an input's value and its setter onto the component's props. */
export type ValueProps<P, V> = (value: V, setValue: (value: V) => void) => Partial<P>;

export type MappingValue = Record<string, { value: string; source: "auto" | "user" }> | null;

export const inputValueProps: {
  AdjustmentEditor: ValueProps<AdjustmentEditorProps, AdjEvent | null>;
  CdCheckbox: ValueProps<CdCheckboxProps, boolean>;
  CdTextArea: ValueProps<CdTextAreaProps, string>;
  ChartCustomize: ValueProps<ChartCustomizeProps, CustomizeValue | null>;
  ChipMulti: ValueProps<ChipMultiProps, ChipMultiValue>;
  ChipNumber: ValueProps<ChipNumberProps, number | null>;
  ChipSelect: ValueProps<ChipSelectProps, string>;
  FieldNumber: ValueProps<FieldNumberProps, number | null>;
  FieldSelect: ValueProps<FieldSelectProps, string>;
  MappingModal: ValueProps<MappingModalProps, MappingValue>;
  WizardSteps: ValueProps<WizardStepsProps, string>;
} = {
  AdjustmentEditor: (value, setValue) => ({ value, onChange: setValue }),
  CdCheckbox: (value, setValue) => ({
    value,
    onChange: (v: boolean) => setValue(v),
  }),
  CdTextArea: (value, setValue) => ({
    value,
    onChange: (v: string) => setValue(v),
  }),
  ChartCustomize: (value, setValue) => ({ value, onChange: setValue }),
  ChipMulti: (value, setValue) => ({ value, onChange: setValue }),
  ChipNumber: (value, setValue) => ({
    value,
    onChange: (v: number) => setValue(v),
  }),
  ChipSelect: (value, setValue) => ({ value, onChange: setValue }),
  FieldNumber: (value, setValue) => ({
    value,
    onChange: (v: number) => setValue(v),
  }),
  FieldSelect: (value, setValue) => ({
    value,
    onChange: (v: string) => setValue(v),
  }),
  MappingModal: (_value, setValue) => ({
    onChange: (v: Record<string, { value: string; source: "auto" | "user" }>) => setValue(v),
  }),
  WizardSteps: (value, setValue) => ({
    value,
    onChange: (key: string) => setValue(key),
  }),
};
