// The page the components run in: what they tell it (an input's value, a click) and what it tells them (messages
// by type). Every call the components make outside React goes through here, so they work with any host: Shiny (the
// default, looked up on window.Shiny when it is first needed, so the order scripts load in does not matter) or one
// given with setUiHost() -- a webview, a plain page, a test.

export interface UiHost {
  /** An input's value, or a one-shot event (`priority: "event"`): a click, a cleared field, a mounted component. */
  setInputValue(id: string, value: unknown, options?: { priority?: "event" | "deferred" | "immediate" }): void;
  /** Called with every message of `type` the host sends. */
  onMessage(type: string, handler: (message: any) => void): void;
  /** Plain-HTML inputs inside `scope` (FileUploadZone's file input) become the host's inputs, and stop being. */
  bindAll?(scope: Element): void;
  unbindAll?(scope: Element): void;
  initializeInputs?(scope: Element): void;
  /** The header's Ask AI button: `from` is the element asked about, or null for the whole page. */
  askAi?(from: Element | null): void;
}

interface ShinyLike {
  setInputValue?: (name: string, value: unknown, options?: { priority?: string }) => void;
  addCustomMessageHandler?: (type: string, handler: (message: unknown) => void) => void;
  bindAll?: (scope?: Element) => void;
  unbindAll?: (scope?: Element) => void;
  initializeInputs?: (scope?: Element) => void;
}

const shiny = (): ShinyLike | undefined =>
  typeof window === "undefined" ? undefined : (window as unknown as { Shiny?: ShinyLike }).Shiny;

// Shiny may finish loading after this bundle, so a handler waits for it (every 50 ms, for 10 seconds at most).
const stopWaiting = new Map<ReturnType<typeof setInterval>, () => void>();

/** Shiny's own window.Shiny: what the components did directly before there was a host. */
export const shinyHost: UiHost = {
  setInputValue(id, value, options) {
    shiny()?.setInputValue?.(id, value, options);
  },
  onMessage(type, handler) {
    const register = (): boolean => {
      const s = shiny();
      if (!s || !s.addCustomMessageHandler) return false;
      s.addCustomMessageHandler(type, handler);
      return true;
    };
    if (register()) return;
    const timer = setInterval(() => {
      if (register()) stop();
    }, 50);
    const limit = setTimeout(() => stop(), 10000);
    const stop = () => {
      clearInterval(timer);
      clearTimeout(limit);
      stopWaiting.delete(timer);
    };
    stopWaiting.set(timer, stop);
  },
  bindAll(scope) {
    shiny()?.bindAll?.(scope);
  },
  unbindAll(scope) {
    shiny()?.unbindAll?.(scope);
  },
  initializeInputs(scope) {
    shiny()?.initializeInputs?.(scope);
  }
};

let current: UiHost | null = null;

/** The host the components talk to: the one given to setUiHost(), else Shiny's. */
export function uiHost(): UiHost {
  return current ?? shinyHost;
}

// Messages. A host may keep one handler per type (Shiny does: a second addCustomMessageHandler() for a type replaces
// the first), so each type the components listen to gets one handler on the host, which hands the message to every
// listener. A new host gets the same handlers, and the old one's are ignored from then on.
const listeners = new Map<string, Set<(message: any) => void>>();
const attachedTo = new Map<string, UiHost>();

function attach(type: string): void {
  const host = uiHost();
  if (attachedTo.get(type) === host) return;
  attachedTo.set(type, host);
  host.onMessage(type, (message) => {
    if (attachedTo.get(type) !== host) return;
    listeners.get(type)?.forEach((listener) => listener(message));
  });
}

/** Listens to the host's messages of `type`, whichever host it is now or later. Returns the way to stop. */
export function onHostMessage(type: string, listener: (message: any) => void): () => void {
  if (!listeners.has(type)) listeners.set(type, new Set());
  listeners.get(type)!.add(listener);
  attach(type);
  return () => {
    listeners.get(type)?.delete(listener);
  };
}

/** The host from now on (null: Shiny's again). Call it before rendering; listeners move to the new host. */
export function setUiHost(host: UiHost | null): void {
  if (host === current) return;
  if (uiHost() === shinyHost && host !== shinyHost) {
    stopWaiting.forEach((stop) => stop());
    stopWaiting.clear();
  }
  current = host;
  listeners.forEach((_, type) => attach(type));
}
